interface PayStrategy { fun pay(amount: Long) }
// إضافة مزود جديد بكلاس مستقل بدون تعديل الكود القديم
class GooglePayStrategy : PayStrategy { override fun pay(amount: Long) { ... } }
// المنسق مغلق للتعديل ويستقبل أي مزود
